    import re
    from datetime import time
    Davomat = apps.get_model('maktab', 'Davomat')
    Guruh = apps.get_model('maktab', 'Guruh')
    Davomat.objects.filter(keldi=False).update(holat='kelmadi')
    for d in Davomat.objects.filter(guruh__isnull=True).select_related('oquvchi'):
        if d.oquvchi.guruh_id:
            d.guruh_id = d.oquvchi.guruh_id
            d.save(update_fields=['guruh'])
    for g in Guruh.objects.filter(boshlanish__isnull=True):
        soat = re.findall(r'(\d{1,2}):(\d{2})', g.vaqt or '')
        if soat:
            g.boshlanish = time(int(soat[0][0]), int(soat[0][1]))
            if len(soat) > 1:
                g.tugash = time(int(soat[1][0]), int(soat[1][1]))
            g.save(update_fields=['boshlanish', 'tugash'])


